arguments.command:
cd /app/ssl && {
  echo "Certificate Verification Report";
  echo "==============================";
  echo;
  echo "Subject: $(openssl x509 -in server.crt -noout -subject | sed 's/^subject=//')";
  echo;
  echo "Validity:";
  echo "  Not Before: $(openssl x509 -in server.crt -noout -startdate | sed 's/^notBefore=//') [$(openssl x509 -in server.crt -noout -startdate | sed 's/^notBefore=//' | xargs -I{} date -u -d "{}" +%Y-%m-%d)]";
  echo "  Not After:  $(openssl x509 -in server.crt -noout -enddate | sed 's/^notAfter=//') [$(openssl x509 -in server.crt -noout -enddate | sed 's/^notAfter=//' | xargs -I{} date -u -d "{}" +%Y-%m-%d)]";
  echo "  Valid From: $(openssl x509 -in server.crt -noout -startdate | sed 's/^notBefore=//' | xargs -I{} date -u -d "{}" +%Y-%m-%d)";
  echo "  Valid Until: $(openssl x509 -in server.crt -noout -enddate | sed 's/^notAfter=//' | xargs -I{} date -u -d "{}" +%Y-%m-%d)";
  echo;
  echo "SHA-256 Fingerprint: $(openssl x509 -in server.crt -noout -fingerprint -sha256 | sed 's/^.*=//')";
} > verification.txt && chmod 644 verification.txt && cat verification.txt
